import XCTest

class TestInteraction: XCTestCase {
    func testNavigateToTeamStandup() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()

        sleep(2)

        // Try to tap the Cancel button on the dialog
        let cancelButton = app.buttons["Cancel"]
        if cancelButton.waitForExistence(timeout: 5) {
            cancelButton.tap()
            sleep(1)
        }

        // Now try to find and tap the Team Standup room
        // Look for text "Team Standup"
        let teamStandupElement = app.staticTexts["Team Standup"]
        if teamStandupElement.waitForExistence(timeout: 5) {
            teamStandupElement.tap()
            sleep(2)
        }
    }
}
EOF

