import XCTest

class ElementTest: XCTestCase {

    func testNavigateToTeamStandup() {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()

        // Wait for app to load
        Thread.sleep(forTimeInterval: 3)

        // Look for "I already have an account" button and tap it
        let accountButton = app.staticTexts["I already have an account"]
        if accountButton.exists {
            accountButton.tap()
            Thread.sleep(forTimeInterval: 2)
        }

        // Try searching for Team Standup
        let searchElement = app.staticTexts["Search"]
        if searchElement.exists {
            searchElement.tap()
            Thread.sleep(forTimeInterval: 1)

            let searchField = app.searchFields.first
            if searchField != nil {
                searchField?.typeText("Team")
            }
        }
    }
}
SWIFT_EOF

